29	
30	const PRESET_CATEGORIES = [
31	  "Fire Marshal", "ID Sign", "Warehouse Manifest",
32	  "Show Bucket", "Vehicle Spotting", "Electrical",
33	];
34	
35	const editItemSchema = z.object({
36	  name: z.string().min(1, "Name is required"),
37	  category: z.string().optional(),
38	  dueDate: z.string().optional(),
39	  dueDateRule: z.string().optional(),
40	  notes: z.string().optional(),
41	});
42	
43	function EditItemDialog({ item, open, onOpenChange, onSuccess }: {
44	  item: any;
45	  open: boolean;
46	  onOpenChange: (v: boolean) => void;
47	  onSuccess: () => void;
48	}) {
49	  const { toast } = useToast();
50	  const updateTask = useUpdateTask();
51	  const updateEblast = useUpdateEblast();
52	
53	  const form = useForm<z.infer<typeof editItemSchema>>({
54	    resolver: zodResolver(editItemSchema),
55	    defaultValues: { name: "", category: "", dueDate: "", dueDateRule: "", notes: "" },
56	  });
57	
58	  useEffect(() => {
59	    if (open) {
60	      form.reset({
61	        name: item.name,
62	        category: item.category ?? "",
63	        dueDate: item.dueDate ? String(item.dueDate).split("T")[0] : "",
64	        dueDateRule: item.dueDateRule ?? "",
65	        notes: item.notes ?? "",
66	      });
67	    }
68	  }, [open, item]);
69	
70	  const onSubmit = (data: z.infer<typeof editItemSchema>) => {
71	    if (item.type === "task") {
72	      updateTask.mutate(
73	        { showId: item.showId, taskId: item.id, data },
74	        {
75	          onSuccess: () => { toast({ title: "Task updated" }); onOpenChange(false); onSuccess(); },
76	          onError: () => toast({ title: "Error updating task", variant: "destructive" }),
77	        }
78	      );
79	    } else {
80	      updateEblast.mutate(
81	        { showId: item.showId, eblastId: item.id, data },
82	        {
83	          onSuccess: () => { toast({ title: "eBlast updated" }); onOpenChange(false); onSuccess(); },
84	          onError: () => toast({ title: "Error updating eBlast", variant: "destructive" }),
85	        }
86	      );
87	    }
88	  };
89	
90	  const isPending = updateTask.isPending || updateEblast.isPending;
91	  const isTask = item.type === "task";
92	
93	  return (
94	    <Dialog open={open} onOpenChange={onOpenChange}>
95	      <DialogContent className="max-w-md" aria-describedby={undefined}>
96	        <DialogHeader>
97	          <DialogTitle>Edit {isTask ? "Task" : "E-Blast"}</DialogTitle>
98	        </DialogHeader>
99	        <Form {...form}>
100	          <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
101	            <FormField control={form.control} name="name" render={({ field }) => (
102	              <FormItem>
103	                <FormLabel>Name *</FormLabel>
104	                <FormControl><Input {...field} /></FormControl>
105	                <FormMessage />
106	              </FormItem>
107	            )} />
108	            <div className="grid grid-cols-2 gap-4">
109	              {isTask && (
110	                <FormField control={form.control} name="category" render={({ field }) => (
111	                  <FormItem>
112	                    <FormLabel>Category</FormLabel>
113	                    <Select onValueChange={field.onChange} value={field.value}>
114	                      <FormControl><SelectTrigger><SelectValue placeholder="None" /></SelectTrigger></FormControl>
115	                      <SelectContent>
116	                        <SelectItem value="none">None</SelectItem>
117	                        {PRESET_CATEGORIES.map(c => <SelectItem key={c} value={c}>{c}</SelectItem>)}
118	                      </SelectContent>
119	                    </Select>
120	                  </FormItem>
121	                )} />
122	              )}
123	              <FormField control={form.control} name="dueDate" render={({ field }) => (
124	                <FormItem className={!isTask ? "col-span-2" : ""}>
125	                  <FormLabel>Due Date</FormLabel>
126	                  <FormControl><Input type="date" {...field} /></FormControl>
127	                </FormItem>
128	              )} />
129	            </div>
130	            <FormField control={form.control} name="dueDateRule" render={({ field }) => (
131	              <FormItem>
132	                <FormLabel>Due Date Rule</FormLabel>
133	                <FormControl><Input placeholder="e.g. 30 cal days before move-in" {...field} /></FormControl>
134	              </FormItem>
135	            )} />
136	            <FormField control={form.control} name="notes" render={({ field }) => (
137	              <FormItem>
138	                <FormLabel>Notes</FormLabel>
139	                <FormControl><Textarea className="resize-none" rows={3} {...field} /></FormControl>
140	              </FormItem>
141	            )} />
142	            <div className="flex justify-end gap-2 pt-2">
143	              <Button variant="outline" type="button" onClick={() => onOpenChange(false)}>Cancel</Button>
144	              <Button type="submit" disabled={isPending}>
145	                {isPending && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
146	                Save
147	              </Button>
148	            </div>
149	          </form>
150	        </Form>
151	      </DialogContent>
152	    </Dialog>
153	  );
154	}
155	
156	const CATEGORY_COLORS: Record<string, string> = {
157	  "Show Bucket":        "bg-blue-500/15 text-blue-400 border-blue-500/30",
158	  "Fire Marshal":       "bg-red-500/15 text-red-400 border-red-500/30",
159	  "ID Sign":            "bg-purple-500/15 text-purple-400 border-purple-500/30",
160	  "Warehouse Manifest": "bg-cyan-500/15 text-cyan-400 border-cyan-500/30",
161	  "Vehicle Spotting":   "bg-amber-500/15 text-amber-400 border-amber-500/30",
162	  eblast:               "bg-pink-500/15 text-pink-400 border-pink-500/30",
163	};
164	
165	function chipClass(type: string, category: string | null | undefined) {
166	  if (type === "eblast") return CATEGORY_COLORS["eblast"];
167	  return CATEGORY_COLORS[category ?? ""] ?? "bg-slate-500/15 text-slate-400 border-slate-500/30";
168	}
169	
170	function itemKey(type: string, id: number) {
171	  return `${type}-${id}`;
172	}
173	
174	function formatTime(secs: number) {
175	  const m = Math.floor(secs / 60).toString().padStart(2, "0");
176	  const s = (secs % 60).toString().padStart(2, "0");
177	  return `${m}:${s}`;
178	}
179	
180	export function DashboardTaskSlider() {
181	  const queryClient = useQueryClient();
182	  const { data: rawItems, isLoading } = useGetOverdueItems();
183	  const updateTask = useUpdateTask();
184	  const updateEblast = useUpdateEblast();
185	
186	  const [index, setIndex] = useState(0);
187	  const [noteDrafts, setNoteDrafts] = useState<Record<string, string>>({});
188	  const [savedFlash, setSavedFlash] = useState<Record<string, boolean>>({});
189	  const [completing, setCompleting] = useState<Record<string, boolean>>({});
190	  const [noteOpen, setNoteOpen] = useState<Record<string, boolean>>({});
191	  const [editOpen, setEditOpen] = useState(false);
192	
193	  // Pomodoro state
194	  const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
195	  const [pomodoroOpen, setPomodoroOpen] = useState(false);
196	  const [presets, setPresets] = useState<[number, number, number]>([2, 5, 30]);
197	  const [selectedPreset, setSelectedPreset] = useState<0 | 1 | 2 | null>(null);
198	  const [timeLeft, setTimeLeft] = useState(0);
199	  const [isRunning, setIsRunning] = useState(false);
200	  const [timesUp, setTimesUp] = useState(false);
201	
202	  const items = useMemo(() => {
203	    if (!rawItems) return [];
204	    const dueToday = rawItems.filter(i => i.daysOverdue === 0);
205	    const overdue = rawItems
206	      .filter(i => i.daysOverdue > 0)
207	      .sort((a, b) => b.daysOverdue - a.daysOverdue);
208	    return [...dueToday, ...overdue];
209	  }, [rawItems]);
210	
211	  // Seed note drafts when items load
212	  useEffect(() => {
213	    if (!items.length) return;
214	    setNoteDrafts(prev => {
215	      const next = { ...prev };
216	      for (const item of items) {
217	        const k = itemKey(item.type, item.id);
218	        if (!(k in next)) next[k] = item.notes ?? "";
219	      }
220	      return next;
221	    });
222	  }, [items]);
223	
224	  // Countdown ticker
225	  useEffect(() => {
226	    if (!isRunning) return;
227	    intervalRef.current = setInterval(() => {
228	      setTimeLeft(t => {
229	        if (t <= 1) {
230	          clearInterval(intervalRef.current!);
231	          setIsRunning(false);
232	          setTimesUp(true);
233	          return 0;
234	        }
235	        return t - 1;
236	      });
237	    }, 1000);
238	    return () => clearInterval(intervalRef.current!);
239	  }, [isRunning]);
240	
241	  // Close pomodoro when navigating to a different card
242	  useEffect(() => {
243	    clearInterval(intervalRef.current!);
244	    setPomodoroOpen(false);
245	    setSelectedPreset(null);
246	    setTimeLeft(0);
247	    setIsRunning(false);
248	    setTimesUp(false);
249	  }, [index]);
250	
251	  const invalidate = () => {
252	    queryClient.invalidateQueries({ queryKey: getGetOverdueItemsQueryKey() });
253	    queryClient.invalidateQueries({ queryKey: getGetDashboardSummaryQueryKey() });
254	  };
255	
256	  if (isLoading) return <Skeleton className="w-full h-40 rounded-lg" />;
257	  if (items.length === 0) return null;
258	
259	  const safeIndex = Math.min(index, items.length - 1);
260	  const item = items[safeIndex];
261	  const isToday = item.daysOverdue === 0;
262	  const total = items.length;
263	  const key = itemKey(item.type, item.id);
264	  const currentNote = noteDrafts[key] ?? item.notes ?? "";
265	  const isCompleting = completing[key] ?? false;
266	  const isNoteOpen = noteOpen[key] ?? false;
267	  const accentText = isToday ? "text-amber-400" : "text-red-400";
268	
269	  // ── Navigation ────────────────────────────────────────────────────────────
270	  const prev = () => setIndex(i => Math.max(0, i - 1));
271	  const next = () => setIndex(i => Math.min(total - 1, i + 1));
272	
273	  // ── Notes ─────────────────────────────────────────────────────────────────
274	  const saveNote = () => {
275	    const draft = currentNote;
276	    const original = item.notes ?? "";
277	    if (draft === original) return;
278	    if (item.type === "task") {
279	      updateTask.mutate(
280	        { showId: item.showId, taskId: item.id, data: { notes: draft || null } },
281	        { onSuccess: () => {
282	            setSavedFlash(p => ({ ...p, [key]: true }));
283	            setTimeout(() => setSavedFlash(p => ({ ...p, [key]: false })), 1500);
284	            invalidate();
285	          }
286	        }
287	      );
288	    } else {
289	      updateEblast.mutate(
290	        { showId: item.showId, eblastId: item.id, data: { notes: draft || null } },
291	        { onSuccess: () => {
292	            setSavedFlash(p => ({ ...p, [key]: true }));
293	            setTimeout(() => setSavedFlash(p => ({ ...p, [key]: false })), 1500);
294	            invalidate();
295	          }
296	        }
297	      );
298	    }
299	  };
300	
301	  const openNote = () => setNoteOpen(p => ({ ...p, [key]: true }));
302	  const closeNote = () => {
303	    saveNote();
304	    setNoteOpen(p => ({ ...p, [key]: false }));
305	  };
306	
307	  // ── Complete / Sent ───────────────────────────────────────────────────────
308	  const markComplete = () => {
309	    setCompleting(p => ({ ...p, [key]: true }));
310	    const now = new Date().toISOString();
311	    if (item.type === "task") {
312	      updateTask.mutate(
313	        { showId: item.showId, taskId: item.id, data: { completed: true, completedAt: now } },
314	        {
315	          onSuccess: () => {
316	            invalidate();
317	            setIndex(i => Math.max(0, Math.min(i, total - 2)));
318	            setCompleting(p => ({ ...p, [key]: false }));
319	          },
320	          onError: () => setCompleting(p => ({ ...p, [key]: false })),
321	        }
322	      );
323	    } else {
324	      updateEblast.mutate(
325	        { showId: item.showId, eblastId: item.id, data: { sent: true, sentAt: now } },
326	        {
327	          onSuccess: () => {
328	            invalidate();
329	            setIndex(i => Math.max(0, Math.min(i, total - 2)));
330	            setCompleting(p => ({ ...p, [key]: false }));
331	          },
332	          onError: () => setCompleting(p => ({ ...p, [key]: false })),
333	        }
334	      );
335	    }
336	  };
337	
338	  // ── Pomodoro helpers ──────────────────────────────────────────────────────
339	  const openPomodoro = () => setPomodoroOpen(true);
340	
341	  const closePomodoro = () => {
342	    clearInterval(intervalRef.current!);
343	    setPomodoroOpen(false);
344	    setSelectedPreset(null);
345	    setTimeLeft(0);
346	    setIsRunning(false);
347	    setTimesUp(false);
348	  };
349	
350	  const selectPreset = (i: 0 | 1 | 2) => {
351	    clearInterval(intervalRef.current!);
352	    setIsRunning(false);
353	    setTimesUp(false);
354	    setSelectedPreset(i);
355	    setTimeLeft(presets[i] * 60);
356	  };
357	
358	  const adjustPreset = (i: 0 | 1 | 2, delta: number) => {
359	    setPresets(p => {
360	      const next: [number, number, number] = [...p] as [number, number, number];
361	      next[i] = Math.max(1, next[i] + delta);
362	      if (selectedPreset === i) {
363	        clearInterval(intervalRef.current!);
364	        setIsRunning(false);
365	        setTimesUp(false);
366	        setTimeLeft(next[i] * 60);
367	      }
368	      return next;
369	    });
370	  };
371	
372	  const toggleTimer = () => {
373	    if (selectedPreset === null) return;
374	    if (timeLeft === 0) {
375	      setTimeLeft(presets[selectedPreset] * 60);
376	      setTimesUp(false);
377	    }
378	    setIsRunning(r => !r);
379	  };
380	
381	  const resetTimer = () => {
382	    clearInterval(intervalRef.current!);
383	    setIsRunning(false);
384	    setTimesUp(false);
385	    if (selectedPreset !== null) setTimeLeft(presets[selectedPreset] * 60);
386	  };
387	
388	  const showTab = item.type === "eblast" ? "eblasts" : "tasks";
389	  const completionLabel = item.type === "eblast" ? "Mark Sent" : "Mark Complete";
390	  const outerBorder = isToday ? "border-amber-500/35 bg-amber-500/[0.06]" : "border-red-500/35 bg-red-500/[0.06]";
391	  const iconRing = isToday ? "bg-amber-500/20" : "bg-red-500/20";
392	  const completeBtn = isToday
393	    ? "bg-amber-500 hover:bg-amber-400 text-black"
394	    : "bg-red-500 hover:bg-red-400 text-white";
395	  // kept for pomodoro view compat
396	  const headerBand = isToday
397	    ? "bg-amber-500/20 border-b border-amber-500/35"
398	    : "bg-red-500/20 border-b border-red-500/35";
399	
400	  // ── Pomodoro view ─────────────────────────────────────────────────────────
401	  if (pomodoroOpen) {
402	    return (
403	      <div className={`rounded-xl border ${outerBorder}`}>
404	        <div className="px-4 pt-4 pb-4 flex flex-col gap-2 min-h-[168px] justify-between">
405	
406	          {/* Row 1: Back (left) · chip (true center) · Focus Timer (right) */}
407	          <div className="relative flex items-center">
408	            <button
409	              onClick={closePomodoro}
410	              className="flex items-center gap-1 text-xs font-medium text-muted-foreground hover:text-foreground transition-colors"
411	            >
412	              <ArrowLeft className="h-3 w-3" />
413	              Back
414	            </button>
415	            <span className={`absolute left-1/2 -translate-x-1/2 text-xs font-semibold px-2 py-0.5 rounded-md border ${chipClass(item.type, item.category)}`}>
416	              {item.type === "eblast" ? "E-Blast" : (item.category ?? "Task")}
417	            </span>
418	            <span className={`ml-auto text-xs font-bold uppercase tracking-widest ${accentText}`}>Focus Timer</span>
419	          </div>
420	
421	          {/* Row 2: task name — centered */}
422	          <p className="text-xl font-bold leading-snug text-center">{item.name}</p>
423	
424	          {/* Row 3: timer readout — centered */}
425	          <div className="flex flex-col items-center gap-0.5">
426	            <span className={`text-3xl font-black tabular-nums tracking-tight ${selectedPreset !== null ? accentText : "text-muted-foreground/30"}`}>
427	              {selectedPreset !== null ? formatTime(timeLeft) : "--:--"}
428	            </span>
429	            {timesUp && <span className={`text-xs font-semibold ${accentText}`}>Time's up!</span>}
430	          </div>
431	
432	          {/* Row 4: presets + Start/Reset — all centered on one line */}
433	          <div className="flex items-center justify-center gap-3 flex-wrap">
434	            {([0, 1, 2] as const).map(i => {
435	              const isSelected = selectedPreset === i;
436	              return (
437	                <div key={i} className="flex items-center gap-0.5">
438	                  <Button variant="ghost" size="icon" className="h-5 w-5" onClick={() => adjustPreset(i, -1)} disabled={presets[i] <= 1}>
439	                    <span className="text-xs leading-none">−</span>
440	                  </Button>
441	                  <button
442	                    onClick={() => selectPreset(i)}
443	                    className={`px-2 py-0.5 rounded text-xs font-medium border transition-colors ${
444	                      isSelected
445	                        ? "bg-primary/15 border-primary/40 text-primary"
446	                        : "border-border text-muted-foreground hover:text-foreground hover:border-muted-foreground"
447	                    }`}
448	                  >
449	                    {presets[i]}m
450	                  </button>
451	                  <Button variant="ghost" size="icon" className="h-5 w-5" onClick={() => adjustPreset(i, 1)}>
452	                    <span className="text-xs leading-none">+</span>
453	                  </Button>
454	                </div>
455	              );
456	            })}
457	
458	            <div className="w-px h-4 bg-border mx-1" />
459	
460	            <Button size="sm" className={`gap-1.5 ${completeBtn}`} onClick={toggleTimer} disabled={selectedPreset === null}>
461	              {isRunning
462	                ? <><Pause className="h-3.5 w-3.5" /> Pause</>
463	                : <><Play className="h-3.5 w-3.5" /> Start</>
464	              }
465	            </Button>
466	            <Button variant="outline" size="icon" className="h-8 w-8" onClick={resetTimer} disabled={selectedPreset === null} title="Reset">
467	              <RotateCcw className="h-3.5 w-3.5" />
468	            </Button>
469	          </div>
470	
471	        </div>
472	      </div>
473	    );
474	  }
475	
476	  // ── Default slider view ───────────────────────────────────────────────────
477	  const moveInDays = item.moveInDate
478	    ? differenceInDays(startOfDay(parseDateStr(item.moveInDate)), startOfDay(new Date()))
479	    : null;
480	  const moveInUrgency = item.moveInDate ? getUrgencyInfo(item.moveInDate) : null;
481	
482	  return (
483	    <div className={`rounded-xl border transition-opacity duration-300 ${isCompleting ? "opacity-40 pointer-events-none" : ""} ${outerBorder}`}>
484	      <div className="px-6 pt-6 pb-5 flex items-start gap-6 min-h-[185px]">
485	
486	        {/* Left: accent icon */}
487	        <div className={`rounded-full p-3.5 shrink-0 self-center ${iconRing}`}>
488	          <AlertTriangle className={`h-10 w-10 ${accentText}`} />
489	        </div>
490	
491	        {/* Content */}
492	        <div className="flex-1 min-w-0 flex flex-col gap-2.5">
493	
494	          {/* Row 1: urgency label + category chip */}
495	          <div className="flex items-center gap-2">
496	            <span className={`text-xs font-bold uppercase tracking-widest shrink-0 ${accentText}`}>
497	              {isToday ? "Due Today" : `${item.daysOverdue} ${item.daysOverdue === 1 ? "Day" : "Days"} Overdue`}
498	            </span>
499	            <span className={`text-xs font-semibold px-2 py-0.5 rounded-md border shrink-0 ${chipClass(item.type, item.category)}`}>
500	              {item.type === "eblast" ? "E-Blast" : (item.category ?? "Task")}
501	            </span>
502	          </div>
503	
504	          {/* Row 2: task name — clickable link to show detail */}
505	          <Link href={`/shows/${item.showId}?tab=${showTab}`}>
506	            <p className="text-xl font-bold leading-snug hover:underline cursor-pointer">{item.name}</p>
507	          </Link>
508	
509	          {/* Row 3: show · due date */}
510	          <p className="text-sm text-muted-foreground">
511	            {item.showName}
512	            <span className="mx-1.5 opacity-40">•</span>
513	            Due {formatDate(item.dueDate)}
514	          </p>
515	
516	          {/* Row 3b: all 6 deadlines on one line */}
517	          <div className="flex items-center gap-0 text-[11px] text-muted-foreground overflow-hidden">
518	            {[
519	              { icon: <Warehouse className="h-3 w-3 shrink-0" />, date: item.advanceWarehouseDate },
520	              { icon: <DollarSign className="h-3 w-3 shrink-0" />, date: item.discountDeadline },
521	              { icon: <Globe className="h-3 w-3 shrink-0" />, date: item.onlineOrderDeadline },
522	              { icon: <Flame className="h-3 w-3 shrink-0" />, date: item.fmDeadlineDate },
523	              { icon: <Signpost className="h-3 w-3 shrink-0" />, date: item.idSignDeadlineDate },
524	              { icon: <Briefcase className="h-3 w-3 shrink-0" />, date: item.bucketDueDate },
525	            ].map((d, i) => (
526	              <span key={i} className="flex items-center whitespace-nowrap">
527	                {i > 0 && i !== 3 && <span className="mx-1.5 opacity-40">|</span>}
528	                {i === 3 && <span className="mx-2 opacity-70 font-bold text-sm">|</span>}
529	                {d.icon}
530	                <span className="ml-1 font-medium text-foreground">
531	                  {d.date ? format(parseDateStr(d.date), "M/d") : "N/A"}
532	                </span>
533	              </span>
534	            ))}
535	          </div>
536	
537	          {/* Row 4: note */}
538	          <div className="flex-1 min-w-0">
539	            {!isNoteOpen ? (
540	              <button
541	                onClick={openNote}
542	                className="flex items-center gap-1.5 text-xs text-muted-foreground hover:text-foreground transition-colors group"
543	              >
544	                <ChevronDown className="h-3 w-3 shrink-0 opacity-50 group-hover:opacity-80" />
545	                <span className="truncate">{currentNote || "Add a note…"}</span>
546	              </button>
547	            ) : (
548	              <div className="flex flex-col gap-1">
549	                <Textarea
550	                  key={key}
551	                  autoFocus
552	                  value={currentNote}
553	                  onChange={e => setNoteDrafts(p => ({ ...p, [key]: e.target.value }))}
554	                  onBlur={closeNote}
555	                  placeholder="Add a note…"
556	                  className="resize-none text-xs min-h-[48px]"
557	                  rows={2}
558	                />
559	                {savedFlash[key] && <span className="text-xs text-muted-foreground">Saved</span>}
560	              </div>
561	            )}
562	          </div>
563	
564	          {/* Pagination dots */}
565	          {total > 1 && total <= 10 && (
566	            <div className="flex items-center gap-1">
567	              {items.map((_, i) => (
568	                <button
569	                  key={i}
570	                  onClick={() => setIndex(i)}
571	                  className={`rounded-full transition-all ${
572	                    i === safeIndex
573	                      ? `h-1.5 w-4 ${isToday ? "bg-amber-400" : "bg-red-400"}`
574	                      : "h-1.5 w-1.5 bg-muted-foreground/30 hover:bg-muted-foreground/50"
575	                  }`}
576	                />
577	              ))}
578	            </div>
579	          )}
580	        </div>{/* /content */}
581	
582	        {/* Right panel: nav · days counter · action buttons — stacked vertically */}
583	        <div className="w-px self-stretch bg-border/50 shrink-0 mx-1" />
584	        <div className="flex flex-col items-center justify-between shrink-0 gap-2 w-[200px]">
585	
586	          {/* Nav arrows — full width */}
587	          <div className="flex items-center justify-between w-full">
588	            <Button variant="ghost" size="icon" className="h-7 w-7" onClick={prev} disabled={safeIndex === 0}>
589	              <ChevronLeft className="h-4 w-4" />
590	            </Button>
591	            <span className="text-xs text-muted-foreground tabular-nums font-medium select-none whitespace-nowrap">
592	              {safeIndex + 1} of {total}
593	            </span>
594	            <Button variant="ghost" size="icon" className="h-7 w-7" onClick={next} disabled={safeIndex === total - 1}>
595	              <ChevronRight className="h-4 w-4" />
596	            </Button>
597	          </div>
598	
599	          {/* Days until move-in box — full width */}
600	          {moveInDays !== null && moveInUrgency && (
601	            <div className={`flex flex-col items-center gap-0 leading-none text-center py-2 rounded-lg border w-full ${
602	              isToday ? "border-amber-500/40 bg-amber-500/[0.06]" : "border-red-500/40 bg-red-500/[0.06]"
603	            }`}>
604	              <span className={`text-4xl font-black tabular-nums tracking-tight ${moveInUrgency.textClass}`}>
605	                {Math.abs(moveInDays)}
606	              </span>
607	              <span className="text-xs uppercase font-semibold tracking-wider text-muted-foreground">
608	                {moveInDays < 0 ? "Days Ago" : "Days"}
609	              </span>
610	              <span className="text-[10px] uppercase tracking-wider text-muted-foreground/60 mt-0.5">Move-In</span>
611	            </div>
612	          )}
613	
614	          {/* Action buttons — full width */}
615	          <div className="flex items-center gap-1.5 justify-between w-full">
616	            <Button variant="outline" size="icon" className="h-8 w-8 shrink-0" onClick={openPomodoro} title="Pomodoro timer">
617	              <Timer className="h-3.5 w-3.5" />
618	            </Button>
619	            <Button variant="outline" size="icon" className="h-8 w-8 shrink-0" onClick={() => setEditOpen(true)} title="Edit">
620	              <Edit2 className="h-3.5 w-3.5" />
621	            </Button>
622	            <Button
623	              size="sm"
624	              className={`gap-1.5 flex-1 ${completeBtn}`}
625	              onClick={markComplete}
626	              disabled={isCompleting}
627	            >
628	              <Check className="h-3.5 w-3.5" />
629	              {completionLabel}
630	            </Button>
631	          </div>
632	
633	        </div>{/* /right panel */}
634	      </div>
635	      <EditItemDialog
636	        item={item}
637	        open={editOpen}
638	        onOpenChange={setEditOpen}
639	        onSuccess={invalidate}
640	      />
641	    </div>
642	  );
643	}
